    // \u7B26\u5408\uFF1A\u91C7\u7528\u5360\u4F4D\u7B26\u7684\u53C2\u6570\u5316\u67E5\u8BE2
    var sqlStr= "SELECT Name, Dept FROM USER WHERE Id = ? AND Pwd = ?"
